<script setup lang="ts">
import {t} from "../i18n"
import { ref, computed, watch, onMounted, onUnmounted } from 'vue'
import draggable from 'vuedraggable'
import { useQuasar } from 'quasar'
import type { Page, Block } from '../types'
import { api, send, ApiError } from '../api'
import { useCms } from '../store'
import Icon from './Icon.vue'
import {themeStyle} from '../domain'
import BlockRenderer from './BlockRenderer.vue'
import MediaLibrary from './MediaLibrary.vue'
import BlockStructure from './BlockStructure.vue'
import {blockTypes,itemTypes,newBlock,findBlock,containingBlocks,cloneBlocks,walkBlocks,blockDepth} from '../blocks'
const clone = <T,>(value: T): T => JSON.parse(JSON.stringify(value))
const props = defineProps<{ page: Page }>(), emit = defineEmits(['close', 'saved']), cms = useCms(), q = useQuasar()
const siteId = cms.selectedId!, base = `/websites/${siteId}/pages/${props.page.id}`
const draft = ref<Page>(clone(props.page)), device = ref('Desktop'), selected = ref<string | null>(draft.value.blocks[0]?.id || null)
const picker = ref(false), saving = ref(false), ready = ref(false), conflict = ref(false), recovery = ref<any>(null)
const revisions = ref<any[]>([]), showRevisions = ref(false), comparison = ref<any>(null), settings = ref(false), scheduleDialog = ref(false), scheduledFor = ref('')
const history = ref<string[]>([]), future = ref<string[]>([]), lastSaved = ref('Loading working copy…'), library = ref('')
const baseline = ref(''), autosaveVersion = ref(0)
let timer: ReturnType<typeof setTimeout> | undefined
let pending: Promise<void> | null = null
const activeColumn=ref(0),itemImageIndex=ref<number|null>(null),savedTemplates=ref<any[]>([]),templatePicker=ref(false)
const block = computed(() => findBlock(draft.value.blocks,selected.value))

const filteredTypes = computed(() => blockTypes.filter(t => t.toLowerCase().includes(library.value.toLowerCase())))
const content = () => ({ title: draft.value.title, slug: draft.value.slug, language: draft.value.language, status: draft.value.status, publish_at: draft.value.publish_at ?? null, blocks: draft.value.blocks, seo: draft.value.seo || {} })
const fingerprint = () => JSON.stringify(content())
const dirty = computed(() => fingerprint() !== baseline.value)
function checkpoint() { history.value.push(JSON.stringify(draft.value.blocks)); if (history.value.length > 50) history.value.shift(); future.value = [] }
function add(type:string) { if(block.value?.children && blockDepth(draft.value.blocks,block.value.id)>=6){q.notify({type:'warning',message:t('Layouts support at most six levels.')});return} if(walkBlocks(draft.value.blocks).length>=100){q.notify({type:'warning',message:t('Pages support up to 100 blocks.')});return} checkpoint(); const b=newBlock(type); if(block.value?.children) block.value.children[Math.min(activeColumn.value,block.value.children.length-1)].push(b); else if(selected.value)(containingBlocks(draft.value.blocks,selected.value)||draft.value.blocks).push(b); else draft.value.blocks.push(b); selected.value=b.id }
function duplicate(){if(!block.value)return;checkpoint();const list=containingBlocks(draft.value.blocks,block.value.id)!;const b=cloneBlocks([block.value])[0];list.splice(list.indexOf(block.value)+1,0,b);selected.value=b.id}
function remove(){if(!block.value)return;checkpoint();const list=containingBlocks(draft.value.blocks,block.value.id)!;list.splice(list.indexOf(block.value),1);selected.value=draft.value.blocks[0]?.id||null}
function addItem(){if(!block.value)return;checkpoint();block.value.items ||= [];block.value.items.push({id:crypto.randomUUID(),title:'New item',text:'Your description',label:'Learn more',link:'#about'})}
async function openTemplates(){try{savedTemplates.value=await api('/websites/'+siteId+'/templates');templatePicker.value=true}catch(e){failure(e)}}
function insertTemplate(t:any){checkpoint();const copies=cloneBlocks(t.blocks);if(block.value?.children)block.value.children[Math.min(activeColumn.value,block.value.children.length-1)].push(...copies);else draft.value.blocks.push(...copies);templatePicker.value=false}
function saveSelected(){if(!block.value)return;const blocks=clone([block.value]);q.dialog({title:t('Save reusable block or section'),prompt:{model:block.value.title||block.value.type,type:'text'},cancel:true}).onOk(async(name:string)=>{try{await api('/websites/'+siteId+'/templates',send('POST',{name,type:blocks[0].children?'Section':'Block',blocks}));q.notify({type:'positive',message:t('Saved to the template library.')})}catch(e){failure(e)}})}
function undo() { const prev = history.value.pop(); if (prev) { future.value.push(JSON.stringify(draft.value.blocks)); draft.value.blocks = JSON.parse(prev) } }
function redo() { const next = future.value.pop(); if (next) { history.value.push(JSON.stringify(draft.value.blocks)); draft.value.blocks = JSON.parse(next) } }
function failure(error: unknown) {
  const e = error as ApiError
  if (e.status === 409) { conflict.value = true; clearTimeout(timer); lastSaved.value = 'Conflict · your local changes are preserved' }
  else lastSaved.value = 'Not saved · check your connection or page fields'
  q.notify({ type: 'negative', message: t(e.message) })
}
async function loadEditor() {
  ready.value = false; clearTimeout(timer)
  try {
    const result = await api(base + '/editor')
    draft.value = result.page; draft.value.seo ||= {}; baseline.value = fingerprint(); autosaveVersion.value = result.autosave?.revision || 0
    recovery.value = result.autosave; conflict.value = false; history.value = []; future.value = []
    selected.value = draft.value.blocks[0]?.id || null; lastSaved.value = result.autosave ? 'A saved working copy is available' : 'All changes saved'; ready.value = true
  } catch (e) { failure(e) }
}
function recover() {
  if (!recovery.value) return
  const stale = recovery.value.base_version !== draft.value.version
  const apply = () => { draft.value = { ...draft.value, ...clone(recovery.value.snapshot) }; recovery.value = null; lastSaved.value = 'Recovered locally · review before publishing'; armAutosave() }
  if (stale) q.dialog({ title:t('Recover an older working copy?'), message:t('The saved page has changed since this copy was made. Review all differences before publishing. Recovery will not change the live website.'), cancel: true }).onOk(apply)
  else apply()
}
async function discardRecovery() {
  try { await api(base + '/autosave', send('DELETE', { autosave_version: autosaveVersion.value })); autosaveVersion.value = 0; recovery.value = null; lastSaved.value = 'All changes saved' } catch (e) { failure(e) }
}
function armAutosave() {
  clearTimeout(timer)
  if (!ready.value || conflict.value || recovery.value || !dirty.value) return
  lastSaved.value = 'Unsaved changes · autosave pending'
  timer = setTimeout(() => { void saveWorkingCopy() }, 2000)
}
async function saveWorkingCopy(manual = false): Promise<void> {
  clearTimeout(timer)
  if (pending) { await pending; if (dirty.value && !conflict.value) return saveWorkingCopy(manual); return }
  if (!ready.value || conflict.value || recovery.value) return
  if (!dirty.value) { if (manual) q.notify({ type: 'info', message: t('Your working copy is already saved.') }); return }
  const snapshot = clone(content()), mark = JSON.stringify(snapshot)
  saving.value = true; lastSaved.value = 'Saving working copy…'
  pending = (async () => {
    try {
      const result = await api(base + '/autosave', send('PUT', { ...snapshot, version: draft.value.version, autosave_version: autosaveVersion.value }))
      autosaveVersion.value = result.autosave_version; baseline.value = mark; lastSaved.value = 'Working copy saved · live page unchanged'
      if (manual) q.notify({ type: 'positive', message: t('Draft saved privately. Your live page has not changed.') })
    } catch (e) { failure(e) }
    finally { saving.value = false; pending = null }
  })()
  await pending
  if (dirty.value && !conflict.value && baseline.value === mark) armAutosave()
}
async function save(status = 'draft') {
  if (status === 'draft') return saveWorkingCopy(true)
  clearTimeout(timer)
  if (pending) await pending
  if (!ready.value || conflict.value || recovery.value) return
  saving.value = true
  const snapshot = clone(content()), before = fingerprint()
  try {
    const result = await api<Page>(base, send('PUT', { ...snapshot, status, publish_at: status === 'scheduled' ? new Date(scheduledFor.value).toISOString() : null, version: draft.value.version, autosave_version: autosaveVersion.value }))
    // Preserve edits made while the request was in flight; only the submitted snapshot was published.
    if (fingerprint() === before) { draft.value = result; baseline.value = fingerprint() }
    else { draft.value.version = result.version; draft.value.status = result.status; draft.value.publish_at = result.publish_at; baseline.value = JSON.stringify({ ...snapshot, status: result.status, publish_at: result.publish_at ?? null }) }
    autosaveVersion.value = 0; lastSaved.value = status === 'scheduled' ? 'Publication scheduled' : 'Published successfully'
    scheduleDialog.value = false; emit('saved'); await cms.load()
    q.notify({ type: 'positive', message: t(status === 'scheduled' ? 'Scheduled. Keep the Laravel scheduler running to publish on time.' : 'Page published. The website must also be published to make it public.') })
  } catch (e) { failure(e) } finally { saving.value = false; if (dirty.value && !conflict.value) armAutosave() }
}
async function loadRevisions() { try { revisions.value = await api(base + '/revisions'); showRevisions.value = true } catch (e) { failure(e) } }
function restore(id: number) {
  q.dialog({ title:t('Restore this revision as a draft?'), message:t('This unpublishes the page. Your previous saved version remains in history. Unsaved local edits will be replaced.'), cancel: true, persistent: true }).onOk(async () => {
    clearTimeout(timer); if (pending) await pending; saving.value = true
    try { await api(base + '/revisions/' + id + '/restore', send('POST', { version: draft.value.version })); showRevisions.value = false; comparison.value = null; await loadEditor(); emit('saved'); q.notify({ type: 'positive', message: t('Revision restored as draft.') }) } catch (e) { failure(e) } finally { saving.value = false }
  })
}
function saveTemplate() { q.dialog({ title:t('Save as template'), message:t('Reuse this page across this website.'), prompt: { model: draft.value.title + ' template', type: 'text' }, cancel: true }).onOk(async (name: string) => { try { await api('/websites/' + siteId + '/templates', send('POST', { name, type: 'Page', blocks: draft.value.blocks })); q.notify({ type: 'positive', message: t('Template saved to your library.') }) } catch (e) { failure(e) } }) }
function downloadDraft() { const url = URL.createObjectURL(new Blob([JSON.stringify(draft.value, null, 2)], { type: 'application/json' })); const a = document.createElement('a'); a.href = url; a.download = draft.value.slug + '-working-copy.json'; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
function reloadLatest() { q.dialog({ title:t('Reload the latest page?'), message:t('Export your local copy first if you want to keep it. Unsaved local changes will be replaced.'), cancel: true }).onOk(loadEditor) }
async function close() {
  clearTimeout(timer); if (pending) await pending
  if (dirty.value || conflict.value) q.dialog({ title:t('Leave the builder?'), message:t('Some local changes are not saved. You can export a copy before leaving.'), cancel: true }).onOk(() => emit('close'))
  else emit('close')
}
const beforeUnload = (event: BeforeUnloadEvent) => { if (dirty.value || pending) { event.preventDefault(); event.returnValue = '' } }
watch(() => fingerprint(), () => { if (ready.value && !saving.value) armAutosave() })
onMounted(() => { void loadEditor(); window.addEventListener('beforeunload', beforeUnload) })
onUnmounted(() => { clearTimeout(timer); window.removeEventListener('beforeunload', beforeUnload) })
</script>
<template><div class="builder"><header class="builder-header"><button class="icon-btn" @click="close" :aria-label="$t('Back to pages')"><Icon name="ArrowLeft"/></button><span class="builder-title"><strong>{{ draft.title }}</strong><small>{{ $t(lastSaved) }}</small></span><div class="device-switch"><button v-for="(icon,d) in {Desktop:'Monitor',Tablet:'Tablet',Mobile:'Smartphone'}" :class="{active:device===d}" @click="device=String(d)" :aria-label="String(d)"><Icon :name="icon" :size="18"/></button></div><button class="icon-btn" @click="undo" :disabled="!history.length" :aria-label="$t('Undo')"><Icon name="Undo2"/></button><button class="icon-btn" @click="redo" :disabled="!future.length" :aria-label="$t('Redo')"><Icon name="Redo2"/></button><button class="icon-btn" @click="loadRevisions" :aria-label="$t('Revision history')"><Icon name="History"/></button><button class="icon-btn" @click="settings=true" :aria-label="$t('Page settings')"><Icon name="Settings2"/></button><button class="btn secondary" @click="save('draft')" :disabled="saving || !ready || conflict || !!recovery">{{ $t("Save draft") }}</button><q-btn unelevated color="primary" :label="$t('Publish')" :disable="!ready || conflict || !!recovery" :loading="saving" @click="save('published')"/><button class="icon-btn" @click="scheduleDialog=true" :disabled="!ready || conflict || !!recovery" :aria-label="$t('Schedule publication')"><Icon name="Clock3"/></button></header><div v-if="!ready" class="editor-notice"><q-spinner size="18px"/> {{ $t("Loading your working copy…") }}</div><div v-if="recovery" class="editor-notice"><span>{{ $t("A private working copy from") }} {{ new Date(recovery.updated_at).toLocaleString() }} {{ $t("is available.") }} {{ $t(recovery.base_version !== draft.version ? 'The saved page has changed since then.' : '') }}</span><button class="btn secondary" @click="recover">{{ $t("Recover copy") }}</button><button class="text-link" @click="discardRecovery">{{ $t("Discard copy") }}</button></div><div v-if="conflict" class="editor-notice conflict"><span>{{ $t("This page or working copy changed in another session. Autosave is paused.") }}</span><button class="btn secondary" @click="downloadDraft">{{ $t("Export my changes") }}</button><button class="btn secondary" @click="reloadLatest">{{ $t("Reload latest") }}</button></div><div class="builder-body" :class="{'editor-disabled':!ready || !!recovery}"><aside class="block-library"><span class="eyebrow">{{ $t("YOUR BUILDING BLOCKS") }}</span><h3>{{ $t("A space for every idea.") }}</h3><div class="inline-search"><Icon name="Search" :size="15"/><input v-model="library" :placeholder="$t('Find a block…')"></div><div class="block-type-grid"><button v-for="type in filteredTypes" @click="add(type)"><Icon :name="type==='Hero'?'PanelTop':type==='Image'?'Image':type==='Text'?'Type':type==='FAQ'?'CircleHelp':'LayoutTemplate'" :size="24"/><span>{{ $t(type) }}</span></button></div><div class="section-heading"><h3>{{ $t("Page structure") }}</h3><span class="count-badge">{{ draft.blocks.length }}</span></div><BlockStructure v-model="draft.blocks" :selected="selected" @select="selected=$event;activeColumn=0" @change="checkpoint"/><button class="text-link template-save" @click="openTemplates"><Icon name="PanelTop" :size="16"/>{{ $t("Insert saved template") }}</button><button class="text-link template-save" @click="saveTemplate"><Icon name="BookmarkPlus" :size="16"/>{{ $t("Save as template") }}</button></aside><div class="builder-canvas"><div class="canvas-label">{{ cms.selected?.domain }} / {{ draft.slug }}<span>{{ device }} {{ $t("preview") }}</span></div><div class="builder-page public-site" :style="{...themeStyle(cms.selected?.appearance||{}),'max-width':device==='Mobile'?'375px':device==='Tablet'?'768px':'100%','--site-primary':cms.selected?.appearance.primary,'--site-bg':cms.selected?.appearance.background,'--site-text':cms.selected?.appearance.text,'--site-radius':cms.selected?.appearance.radius+'px'}"><header class="public-header"><a>{{ cms.selected?.name }}</a><nav><a>{{ $t("Home") }}</a><a>{{ $t("About") }}</a></nav></header><div v-for="b in draft.blocks" :key="b.id" :class="['editable-block',{selected:selected===b.id,hidden:b.hidden}]" @click="selected=b.id"><span class="block-label">{{ $t(b.type) }} {{ b.hidden?'· Hidden':'' }}</span><BlockRenderer :blocks="[{...b,hidden:false}]" :selected-id="selected" editable @select="selected=$event;activeColumn=0"/></div><button class="add-section" @click="add('Text')"><Icon name="Plus" :size="22"/>{{ $t("Add a section") }}</button></div></div><aside class="block-properties" v-if="block"><div class="section-heading"><h3>{{ $t(block.type) }} {{ $t("settings") }}</h3><Icon name="SlidersHorizontal" :size="17"/></div><p class="muted">{{ $t("The little details make it yours.") }}</p><template v-if="block.children"><q-select outlined v-model="activeColumn" :options="$translatedOptions(block.children.map((_,i)=>({label:'Column '+(i+1),value:i})))" emit-value map-options :label="$t('Add new blocks to')"/><div class="layout-column-controls"><button v-if="block.type==='Columns' && block.children.length<4" class="btn secondary" @click="checkpoint();block.children.push([])">{{ $t("Add column") }}</button><button v-if="block.children.length>1" class="text-link" :disabled="!!block.children[block.children.length-1].length" @click="checkpoint();block.children.pop();activeColumn=0">{{ $t("Remove empty last column") }}</button></div></template><q-input outlined v-model="block.title" :label="$t('Heading')" @focus="checkpoint" type="textarea" autogrow/><q-input outlined v-model="block.text" :label="$t('Content')" @focus="checkpoint" type="textarea" rows="5"/><q-input outlined v-model="block.button" :label="$t('Button / question text')" @focus="checkpoint"/><q-input outlined v-model="block.link" :label="$t(block.type==='Video'?'Direct MP4 / WEBM URL':'Button link / URL')" @focus="checkpoint"/><label class="field-label">{{ $t("Image") }}</label><button class="image-selector" @click="itemImageIndex=null;picker=true"><img v-if="block.image" :src="block.image"><Icon v-else name="ImagePlus" :size="28"/><span>{{ $t(block.image?'Replace image':'Choose from media library') }}</span></button><q-input outlined v-model="block.imageAlt" :label="$t('Image alternative text')" @focus="checkpoint"/><template v-if="block.image"><button v-if="!block.imageStyle" class="text-link" @click="checkpoint();block.imageStyle={fit:'cover',position:'center',radius:12,opacity:1}">{{ $t("Customize image display") }}</button><template v-if="block.imageStyle"><q-select emit-value map-options outlined v-model="block.imageStyle.fit" :options="$translatedOptions(['cover','contain'])" :label="$t('Object fit')"/><q-select emit-value map-options outlined v-model="block.imageStyle.position" :options="$translatedOptions(['center','top','bottom','left','right'])" :label="$t('Focal position')"/><label class="field-label">{{ $t("Image radius") }}</label><q-slider v-model="block.imageStyle.radius" :min="0" :max="100"/><label class="field-label">{{ $t("Image opacity") }}</label><q-slider v-model="block.imageStyle.opacity" :min="0" :max="1" :step="0.05"/></template></template><template v-if="itemTypes.includes(block.type)"><div class="section-heading"><h3>{{ $t("Content items") }}</h3><button class="icon-btn" @click="addItem" :aria-label="$t('Add content item')"><Icon name="Plus" :size="16"/></button></div><draggable v-model="block.items" item-key="id" handle=".item-drag" @start="checkpoint"><template #item="{element,index}"><details class="block-item-editor"><summary><Icon name="GripVertical" :size="13" class="item-drag"/>{{ element.title||'Item '+(index+1) }}</summary><q-input outlined dense v-model="element.title" :label="$t('Title')" @focus="checkpoint"/><q-input outlined dense v-model="element.text" :label="$t('Description / answer')" type="textarea" rows="2" @focus="checkpoint"/><q-input v-if="block.type==='Pricing'" outlined dense v-model="element.price" :label="$t('Price display (e.g. USD 29/month)')"/><q-input v-if="['Team','Testimonials'].includes(block.type)" outlined dense v-model="element.role" :label="$t('Role / attribution')"/><button class="image-selector" @click="itemImageIndex=index;picker=true"><img v-if="element.image" :src="element.image"><span>{{ $t(element.image?'Replace item image':'Choose item image') }}</span></button><q-input outlined dense v-model="element.label" :label="$t('Link label')"/><q-input outlined dense v-model="element.link" :label="$t('Link URL')"/><button class="text-link danger" @click="checkpoint();block.items?.splice(index,1)">{{ $t("Delete item") }}</button></details></template></draggable></template><button class="text-link template-save" @click="saveSelected"><Icon name="BookmarkPlus" :size="16"/>{{ $t("Save this block / section") }}</button><q-select emit-value map-options outlined v-model="block.align" :options="$translatedOptions(['start','center','end'])" :label="$t('Text alignment')"/><q-toggle v-model="block.hidden" :label="$t('Hide this block')" color="primary"/><div class="block-actions"><button class="btn secondary" @click="duplicate"><Icon name="Copy" :size="16"/>{{ $t("Duplicate") }}</button><button class="icon-btn danger" @click="remove" :aria-label="$t('Delete block')"><Icon name="Trash2" :size="18"/></button></div></aside></div></div><q-dialog v-model="picker"><q-card class="media-picker-dialog"><div class="dialog-heading"><h2>{{ $t("Find the perfect image") }}</h2><button class="icon-btn" @click="picker=false"><Icon name="X"/></button></div><MediaLibrary :site-id="cms.selectedId!" picker @select="(m:any)=>{checkpoint();if(block){if(itemImageIndex!==null&&block.items?.[itemImageIndex])block.items[itemImageIndex].image=m.url;else {block.image=m.url;block.imageAlt=m.alt}}picker=false}"/></q-card></q-dialog><q-dialog v-model="settings"><q-card class="standard-dialog"><h2>{{ $t("Page details & SEO") }}</h2><q-input outlined v-model="draft.title" :label="$t('Page title')"/><q-input outlined v-model="draft.slug" :label="$t('URL slug')"/><q-select emit-value map-options outlined v-model="draft.language" :options="$translatedOptions(['en','fa','ps','ar'])" :label="$t('Content language')"/><q-input outlined v-model="draft.seo.title" :label="$t('SEO title')"/><q-input outlined v-model="draft.seo.description" :label="$t('Meta description')" type="textarea" rows="3"/><q-input outlined v-model="draft.seo.canonical" :label="$t('Canonical URL (optional)')" type="url"/><q-select emit-value map-options outlined v-model="draft.seo.robots" :options="$translatedOptions(['index,follow','noindex,follow','noindex,nofollow'])" :label="$t('Search engine indexing')"/><q-input outlined v-model="draft.seo.og_title" :label="$t('Social share title')"/><q-input outlined v-model="draft.seo.og_description" :label="$t('Social share description')" type="textarea" rows="2"/><div class="seo-preview"><small>{{ cms.selected?.domain }}/{{ draft.slug }}</small><h3>{{ draft.seo.title||draft.title }}</h3><p>{{ draft.seo.description||$t('Add a description to help people discover this page.') }}</p></div><button class="btn primary" @click="settings=false;save('draft')">{{ $t("Save details") }}</button></q-card></q-dialog><q-dialog v-model="showRevisions"><q-card class="standard-dialog"><h2>{{ $t("A little trip back in time.") }}</h2><p>{{ $t("Restore a previous version as a draft. Your current version will be preserved.") }}</p><div v-for="r in revisions" class="revision-row"><div><strong>{{ r.snapshot.title }}</strong><small>{{ new Date(r.created_at).toLocaleString() }} · {{ r.snapshot.blocks.length }} {{ $t("blocks") }}</small></div><button class="text-link" @click="comparison=r">{{ $t("Compare") }}</button><button class="btn secondary" @click="restore(r.id)">{{ $t("Restore") }}</button></div><p v-if="!revisions.length" class="empty-text">{{ $t("Your first revision appears after you save a change.") }}</p></q-card></q-dialog><q-dialog v-model="scheduleDialog"><q-card class="standard-dialog"><h2>{{ $t("Publish at the right moment.") }}</h2><p>{{ $t("Choose a future time in your browser timezone. Scheduling a published page takes it offline until this time.") }}</p><q-input outlined v-model="scheduledFor" type="datetime-local" :label="$t('Publication date & time')"/><div class="dialog-footer"><button class="btn secondary" @click="scheduleDialog=false">{{ $t("Cancel") }}</button><q-btn color="primary" unelevated :label="$t('Schedule publication')" :loading="saving" :disable="!scheduledFor || Date.now() >= new Date(scheduledFor).getTime()" @click="save('scheduled')"/></div></q-card></q-dialog><q-dialog :model-value="!!comparison" @update:model-value="comparison=null"><q-card class="comparison-dialog" v-if="comparison"><div class="dialog-heading"><h2>{{ $t("Revision comparison") }}</h2><button class="icon-btn" @click="comparison=null"><Icon name="X"/></button></div><div class="comparison-grid"><section><h3>{{ $t("Current working copy") }}</h3><pre>{{ JSON.stringify(content(),null,2) }}</pre></section><section><h3>{{ new Date(comparison.created_at).toLocaleString() }}</h3><pre>{{ JSON.stringify(comparison.snapshot,null,2) }}</pre></section></div></q-card></q-dialog><q-dialog v-model="templatePicker"><q-card class="standard-dialog"><h2>{{ $t("Your reusable building blocks.") }}</h2><div class="revision-row" v-for="t in savedTemplates" :key="t.id"><div><strong>{{ t.name }}</strong><small>{{ $t(t.type) }} · {{ t.blocks.length }} {{ $t("blocks") }}</small></div><button class="btn secondary" @click="insertTemplate(t)">{{ $t("Insert") }}</button></div><p v-if="!savedTemplates.length" class="empty-text">{{ $t("Save a page, section or block to build your library.") }}</p></q-card></q-dialog></template>
